import math,random,json,re,hashlib
from collections import Counter
from pathlib import Path
from vs import refcorpus,path
from extract_works import blocks
from battery import Markov,SOURCE,PAD_ALPHABETS
from transforms import encode,decode,side_bits

def extract(cid,start,stop):
 e=next(e for e in refcorpus.pins() if e['id']==cid);raw=Path(path(e['file'])).read_bytes();assert hashlib.sha256(raw).hexdigest()==e['sha256'];text=raw.decode(e.get('encoding','utf-8'),errors='replace');a=text.index(start);b=text.index(stop,a);body=re.sub(r'\[[\s\S]*?\]',' ',text[a:b]);normalized=refcorpus.normalize(body,'latin');return blocks(normalized),{'id':cid,'pin_sha256':e['sha256'],'normalized_sha256':hashlib.sha256(normalized.encode()).hexdigest(),'blocks':len(blocks(normalized))}

def events(block):
 prefix='';starts=[];marker=False
 for c in block:
  kind='p' if marker else 's';yield kind,prefix,starts,c
  if kind=='s':
   starts=starts+[len(prefix)];marker=(c!=' ')
  else:marker=False
  prefix+=c

def ctx(prefix,starts,n,kind):
 if not n:return ''
 if kind=='output':return prefix[-n:]
 return prefix[starts[-n]:] if len(starts)>=n else prefix
class Model:
 def __init__(self,bs,kind,n,form):
  self.kind,self.n,self.form=kind,n,form;self.tables={t:[{} for _ in range(n+1)] for t in ('s','p')}
  for b in bs:
   for state,prefix,starts,ch in events(b):
    for k in range(n+1):
     key=ctx(prefix,starts,k,form);self.tables[state][k].setdefault(key,Counter())[ch]+=1
 def bits(self,bs):
  total=0
  for b in bs:
   for state,prefix,starts,ch in events(b):
    alphabet=SOURCE if state=='s' else PAD_ALPHABETS[self.kind]; tab=self.tables[state];base=tab[0].get('',Counter());q=(base[ch]+.5)/(base.total()+.5*len(alphabet))
    for k in range(1,self.n+1):
     row=tab[k].get(ctx(prefix,starts,k,self.form));
     if row:q=(row[ch]+2*q)/(row.total()+2)
    total-=math.log2(q)
  return total

def enc(bs,kind,seed):
 result=[encode(b,kind,seed+i) for i,b in enumerate(bs)];assert all(decode(y,kind)==b for b,y in zip(bs,result));return result
train,tm=extract('la_erasmus','Quo saepius est ars medicinae','                     Dixi.');test,em=extract('la_patrick','Tria sunt sub omnipotentis Dei manu habitacula',"End of Project Gutenberg")
assert len(train)>=64 and len(test)>=20
train=train[:64];test=test[:40];N=sum(map(len,test));folds=[]
for f in range(3):
 validation=train[f*16:(f+1)*16];fitting=train[:f*16]+train[(f+1)*16:];vals=Markov.fit(fitting,SOURCE).bits(validation);folds.append({'fold':f,'order':min(range(9),key=lambda k:vals[k]),'validation_bits':vals})
order=min(range(9),key=lambda k:sum(f['validation_bits'][k] for f in folds));sourcebits=Markov.fit(train,SOURCE).bits(test)[order];res={'training':tm,'evaluation':em,'training_blocks_used':64,'evaluation_blocks_used':len(test),'source_symbols':N,'folds':folds,'selected_order':order,'source_bits':sourcebits,'cases':[]}
for kind in ('addB','matched_deterministic','matched_random'):
 for seed in (1,2,3):
  tr=enc(train,kind,seed*10000);ev=enc(test,kind,seed*10000+5000);row={'kind':kind,'seed':seed,'out_symbols':sum(map(len,ev)),'inverse_bits':sourcebits+sum(side_bits(b,kind) for b in test)}
  for form in ('output','source'):
   row[form+'_bits']=Model(tr,kind,order,form).bits(ev)
  res['cases'].append(row)
print(json.dumps(res,indent=2))
